head.script:
scwin.screenId = "jldfil45101";

///////// 1. 변수 및 선언 영역 /////////

scwin.engMandatory1YnCnt = 0;

scwin.otherFormObj = undefined;

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.viewWin = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_submittedDocumentList", fn: function(){ return ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "submittedDocumentList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("submittedDocumentList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "submittedDocumentList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("submittedDocumentList")))).length === 0)); } }, { id: "c_otherwise_61", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "doc.docType"); })() === '1'))); } }, { id: "c_when_65_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.langTpCd"); })() === '1'); } }, { id: "c_otherwise_66", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "doc.langTpCd"); })() === '1'))); } }, { id: "if_writingDocumentList", fn: function(){ return ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "writingDocumentList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("writingDocumentList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "writingDocumentList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("writingDocumentList")))).length === 0)); } }, { id: "btn_goWrite", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'F'); } }, { id: "btn_goViewer_2", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'M'); } }, { id: "btn_goViewer_3", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsAcptTpCd"); })() === 'A'); } }, { id: "c_when_79", fn: function(){ return ((dma_subdoc.get("docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'); } }, { id: "c_otherwise_87", fn: function(){ return (!(((dma_subdoc.get("docNo") ?? (() => { throw new Error("unresolved:" + "subdoc.docNo"); })()) === '00000000000000'))); } }, { id: "if_disclsTitle_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "doc.disclsTitle"); })() !== ''); } }, { id: "if_wrtrptMaindocTpCd", fn: function(){ return ((dma_subdoc.get("wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }, { id: "c_otherwise_96", fn: function(){ return (!(((dma_subdoc.get("wrtYn") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtYn"); })()) === 'Y'))); } }, { id: "if_wrtrptMaindocTpCd_2", fn: function(){ return ((dma_subdoc.get("wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '2'); } }, { id: "if_wrtrptMaindocTpCd_3", fn: function(){ return ((dma_subdoc.get("wrtrptMaindocTpCd") ?? (() => { throw new Error("unresolved:" + "subdoc.wrtrptMaindocTpCd"); })()) === '1'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_56", entity: "dlt_submittedDocumentList", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return "- (영문)" + String(v("formKorNm")); } }, { childId: "__rc1", fn: function (v, i) { return "- " + String(v("formKorNm")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("disclsProcsStatNm")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("disclsProcsDdTm")); } }, { childId: "__rc4", fn: function (v, i) { return String(v("disclsAcptTpNm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getTotalRow();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb5", fn: function () { return " " + String(dma_subdoc.get("formKorNm")) + " " + String(dma_subdoc.get("formEngNm")); } },
        { childId: "__rb6", fn: function () { return "(" + String(dlt_submittedDocumentList.getCellData(0, "disclsTitle")) + ")"; } },
        { childId: "__rb7", fn: function () { return dlt_submittedDocumentList.getCellData(0, "lstChgDdtm"); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["corpUsrTpCd"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil45101' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.goWrite = goWrite;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil45101.onpageload' });
    }
};


